function [tau] = mtq_boresight(e3, a, we, kp, kd)
%MTQ_BORESIGHT  P8 Celani 2026: the boresight e3 onto the target a, the roll about e3 left free:
%   tau = k_p (e3 x a) - k_d w_e.
%   e3: real[1][3] (passed a plain number)
%   a: real[1][3] (passed a plain number)
%   we: real[1][3] (passed a plain number)
%   kp: real[1] (passed a plain number)
%   kd: real[1] (passed a plain number)
%   returns tau: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = zeros(3, 1);
    c = [e3(2)*a(3) - e3(3)*a(2); e3(3)*a(1) - e3(1)*a(3); e3(1)*a(2) - e3(2)*a(1)];
    for i = (0):((3) - 1)
        tau((i) + 1) = ((kp * c((i) + 1)) - (kd * we((i) + 1)));
    end
end
